extends SceneTree
## What cuts each doorway passage and leaf sweep the physics validator turns
## down, collider by collider, on floors built as the game builds them: seeds
## 19, 104, 121 and 7, and the standby floor of hotel_main.build_floor()
## (candidate(404, 0, true)). (4d, tramo final, segunda causa.)
const FLOOR := preload("res://game/world/generation/floor_definition.gd")

var query: PhysicsShapeQueryParameters3D

func _initialize() -> void: run.call_deferred()

func run() -> void:
    var capsule := CapsuleShape3D.new()
    capsule.radius = 0.32
    capsule.height = 1.8
    query = PhysicsShapeQueryParameters3D.new()
    query.shape = capsule
    query.collision_mask = 1
    var level = load("res://game/app/hotel.tscn").instantiate()
    root.add_child(level)
    level.creature_scene = "none"
    level.set_floor(2)
    var kind = level.kind
    for seed_value: int in [19, 104, 121, 7, 404]:
        var manifest: Dictionary
        if seed_value == 404:
            manifest = kind.GENERATOR.new().candidate(404, 0, true)
            manifest["fallback"] = true
        else:
            manifest = kind.GENERATOR.new().generate(seed_value, 1)
        var hotel = kind.GEOMETRY.new()
        root.add_child(hotel)
        await hotel.build(manifest)
        await physics_frame
        await physics_frame
        var world: World3D = hotel.get_world_3d()
        var validator = kind.VALIDATOR.new()
        var errors: Array = validator.validate_physics(world, manifest)
        print("FLOOR seed=%d fallback=%s errors=%s" % [seed_value, str(manifest.get("fallback", false)), str(errors)])
        for e: String in errors:
            if not (e.begins_with("passage_") or e.begins_with("leaf_arc_")): continue
            var ids := e.trim_prefix("leaf_arc_").trim_prefix("passage_").split("_")
            var a: Dictionary = manifest.rooms[int(ids[0])]
            var b: Dictionary = manifest.rooms[int(ids[1])]
            print("CASE %s seed=%d" % [e, seed_value])
            describe(a)
            describe(b)
            print("  DOOR %s" % str(manifest.get("doors", {}).get("%d:%d" % [int(a.id), int(b.id)], {})))
            if e.begins_with("passage_"): passage(world, validator, a, b)
            else: leaf(world, manifest, a, b)
        hotel.queue_free()
        await process_frame
        await process_frame
    print("PASSAGE_PROBE done")
    quit(0)

func describe(room: Dictionary) -> void:
    var at := FLOOR.position_of(room)
    print("  ROOM %d type=%d span=%.2fx%.2f centre=(%.2f, %.2f, %.2f)" % [int(room.id), int(room.type), float(room.span_x), float(room.span_z), at.x, at.y, at.z])
    print("    doors=%s hides=%s open_sides=%s columns=%s" % [str(room.get("doors", [])), str(room.get("hides", [])), str(room.get("open_sides", [])), str(room.get("columns", []))])
    for it in room.get("furniture", []):
        print("    PIECE %s at=%s size=%s turn=%s" % [String(it.kind), str(it.at), str(it.size), str(it.get("turn", 0))])
    for prop in room.get("props", []):
        print("    PROP %s" % str(prop))

## The validator's own way through the doorway, leg by leg: where each cut
## leg stops and what the capsule touches there.
func passage(world: World3D, validator, a: Dictionary, b: Dictionary) -> void:
    var path: Array = validator.passage_path(a, b)
    var shown: Array = []
    for p: Vector3 in path: shown.append(local(p, a))
    print("  PATH from %d: %s" % [int(a.id), str(shown)])
    var space := world.direct_space_state
    for leg in path.size() - 1:
        var from: Vector3 = path[leg]
        var motion: Vector3 = path[leg + 1] - from
        query.transform = Transform3D(Basis.IDENTITY, from)
        query.motion = motion
        var cast := space.cast_motion(query)
        if cast[0] >= 0.99: continue
        print("  LEG %d cut at %.3f, from %s to %s" % [leg, cast[0], local(from, a), local(from + motion, a)])
        query.motion = Vector3.ZERO
        query.transform = Transform3D(Basis.IDENTITY, from + motion * cast[1])
        hits(space, query, a)

## The validator's leaf sweep (map_validator.validate_physics()), angle by angle.
func leaf(world: World3D, data: Dictionary, a: Dictionary, b: Dictionary) -> void:
    var box := BoxShape3D.new()
    box.size = Vector3(FLOOR.LEAF_WIDTH - 0.3, 2.3, 0.05)
    var sweep := PhysicsShapeQueryParameters3D.new()
    sweep.shape = box
    sweep.collision_mask = 1 | 8
    var spec: Dictionary = data.doors["%d:%d" % [int(a.id), int(b.id)]]
    var centre := FLOOR.portal_between(a, b)
    var yaw := FLOOR.leaf_yaw(a, b, spec)
    var turn := FLOOR.leaf_turn(a, b, spec, centre, yaw)
    var hinge := centre + Basis(Vector3.UP, yaw) * Vector3(-FLOOR.LEAF_WIDTH * 0.5, 0, 0)
    print("  HINGE %s turn=%.0f" % [local(hinge, a), turn])
    var space := world.direct_space_state
    for angle: float in [0.6, 0.9, 1.2, 1.48]:
        var turned := Basis(Vector3.UP, yaw + turn * angle)
        sweep.transform = Transform3D(turned, hinge + turned * Vector3(FLOOR.LEAF_WIDTH * 0.5, 1.25, 0))
        if space.intersect_shape(sweep, 1).is_empty(): continue
        print("  ANGLE %.2f leaf middle at %s" % [angle, local(sweep.transform.origin, a)])
        hits(space, sweep, a)

## Each collider the shape overlaps: its node and four parents, its shape and
## where it stands; then the contact points on them, all in a's room space.
func hits(space: PhysicsDirectSpaceState3D, params: PhysicsShapeQueryParameters3D, a: Dictionary) -> void:
    for hit: Dictionary in space.intersect_shape(params, 8):
        var collider: Object = hit.collider
        var chain := ""
        var node := collider as Node
        for _i in 5:
            if node == null: break
            chain += String(node.name) + " < "
            node = node.get_parent()
        var shape := "?"
        var at := "?"
        var layer := -1
        if collider is CollisionObject3D:
            var body := collider as CollisionObject3D
            var holder := body.shape_find_owner(int(hit.shape))
            shape = shape_text(body.shape_owner_get_shape(holder, 0))
            at = local((body.global_transform * body.shape_owner_get_transform(holder)).origin, a)
            layer = body.collision_layer
            var part = body.shape_owner_get_owner(holder)
            if part is Node and part != body: chain = String(part.name) + " < " + chain
        print("    HIT %s shape=%s shape_at=%s layer=%d" % [chain, shape, at, layer])
    var touches: Array = []
    var points := space.collide_shape(params, 8)
    for i in range(1, points.size(), 2): touches.append(local(points[i], a))
    print("    TOUCH %s" % str(touches))

func shape_text(shape: Shape3D) -> String:
    if shape is BoxShape3D: return "Box%s" % str((shape as BoxShape3D).size)
    if shape is CapsuleShape3D: return "Capsule(r=%.2f h=%.2f)" % [(shape as CapsuleShape3D).radius, (shape as CapsuleShape3D).height]
    if shape is CylinderShape3D: return "Cylinder(r=%.2f h=%.2f)" % [(shape as CylinderShape3D).radius, (shape as CylinderShape3D).height]
    return shape.get_class() if shape != null else "null"

func local(point: Vector3, room: Dictionary) -> String:
    var p := point - FLOOR.position_of(room)
    return "(%.2f, %.2f, %.2f)" % [p.x, p.y, p.z]

